"""Original FR/EN application questions based on SERA, checked 2026-09-22."""
import json
import sys
sys.dont_write_bytecode = True
from ppl_alignment_lessons import ROOT, SERA, lesson


def main():
    lesson('PPL_AIRLAW_012', 'air_law', 'Priorités et prévention des collisions', 'Right of way and collision avoidance', SERA, [
        ('Face-à-face et convergence', 'Head-on and converging traffic',
         'Objectif : reconnaître la géométrie de rencontre avant de choisir une action. En rapprochement de face avec risque de collision, chacun vire à sa droite. En convergence à peu près au même niveau entre deux avions motorisés ordinaires, celui qui voit l’autre à sa droite cède le passage. L’avion prioritaire maintient normalement cap et vitesse, mais la responsabilité d’éviter une collision demeure pour les deux pilotes. Celui qui cède évite de passer devant, au-dessus ou au-dessous, sauf en restant largement à l’écart et en tenant compte du sillage. Exemple : vous volez vers le nord, un avion vient de l’est vers votre trajectoire : il est à votre droite, vous cédez.',
         'Objective: identify encounter geometry before selecting an action. In a head-on encounter with collision risk, both aircraft turn to their own right. When two ordinary powered aeroplanes converge at approximately the same level, the pilot with the other aircraft on the right gives way. The aircraft with priority normally maintains heading and speed, but both pilots remain responsible for avoiding collision. The yielding aircraft avoids passing ahead, above or below unless well clear and accounting for wake turbulence. Example: you fly north and an aircraft approaches your track from the east: it is on your right, so you give way.'),
        ('Exceptions et dépassement', 'Exceptions and overtaking',
         'En convergence, un avion motorisé cède aux dirigeables, planeurs et ballons ; un dirigeable cède aux planeurs et ballons ; un planeur cède aux ballons. Un aéronef motorisé cède aussi à un aéronef vu remorquant un autre aéronef ou un objet. Céder également à un aéronef dont on sait la manœuvrabilité dégradée. Le dépassement est une autre situation : l’aéronef rattrapé est prioritaire. Un avion qui le dépasse modifie son cap à droite et reste responsable de l’écartement jusqu’à être entièrement passé et dégagé, même si les positions relatives évoluent. Un planeur dépassant un autre planeur peut passer à droite ou à gauche : ne pas généraliser cette exception aux avions.',
         'When converging, a powered aeroplane gives way to airships, sailplanes and balloons; an airship gives way to sailplanes and balloons; a sailplane gives way to balloons. A powered aircraft also gives way to an aircraft seen towing another aircraft or object. Give way to an aircraft known to have impaired manoeuvrability. Overtaking is a different encounter: the overtaken aircraft has priority. An overtaking aeroplane alters heading to the right and remains responsible for keeping clear until entirely past and clear, even if relative positions change. A sailplane overtaking another sailplane may pass on either side; this exception does not apply to aeroplanes.'),
        ('Approche et atterrissage', 'Approach and landing',
         'Les aéronefs en vol ou au sol cèdent à ceux qui atterrissent ou sont en finale. Entre deux aéronefs plus lourds que l’air en approche, le plus haut cède au plus bas ; ce dernier ne peut pas utiliser cette règle pour couper devant un aéronef en finale ou le dépasser. Les avions motorisés cèdent aux planeurs. Un aéronef connu en atterrissage forcé reçoit la priorité. Ces règles ne dispensent jamais de surveiller ni de respecter les instructions applicables : une priorité ne justifie pas une trajectoire dangereuse.',
         'Aircraft in flight or on the surface give way to aircraft landing or on final approach. Between two heavier-than-air aircraft approaching to land, the higher gives way to the lower; the lower aircraft must not use this rule to cut ahead of or overtake an aircraft on final. Powered aeroplanes give way to sailplanes. Give priority to an aircraft known to be making a forced landing. These rules never remove the need for lookout or compliance with applicable instructions: priority does not justify a hazardous flight path.'),
        ('Roulage, piste et barre d’arrêt', 'Taxiing, runway and stop bar',
         'Au roulage, céder aux aéronefs au décollage ou sur le point de décoller. En convergence au sol, céder à celui qui vient de droite. Face à face, s’arrêter ou, si possible, tourner à droite en restant largement à l’écart. Sur un aérodrome contrôlé, s’arrêter aux points d’attente de piste sauf clairance explicite d’entrée ou de traversée. Une barre d’arrêt allumée impose l’arrêt : une clairance radio seule ne suffit pas à la franchir. Il faut son extinction et la clairance requise. En cas de contradiction, rester arrêté et demander une clarification ; les procédures de panne sont gérées par l’organisme compétent.',
         'When taxiing, give way to aircraft taking off or about to take off. For converging surface traffic, give way to the aircraft on your right. Head-on, stop or, where practicable, turn right while keeping well clear. At a controlled aerodrome, stop at runway holding positions unless explicitly cleared to enter or cross. A lighted stop bar requires a stop: a radio clearance alone does not authorise crossing it. It must be extinguished and the required clearance obtained. If indications conflict, remain stopped and request clarification; equipment failure contingencies are managed by the responsible unit.')],
        '''1|Deux avions se rapprochent de face avec risque de collision. Quelle action est prévue ?|Two aeroplanes approach head-on with collision risk. What action is prescribed?|Chacun vire à sa droite~Chacun vire à sa gauche~Seul le plus rapide vire~Chacun monte|Both turn to their own right~Both turn to their own left~Only the faster turns~Both climb|SERA.3210(c)(1) prescrit une modification de cap à droite pour chacun.|SERA.3210(c)(1) prescribes a heading change to the right for both.
1|Vous volez vers le nord. Un avion motorisé ordinaire converge depuis l’est au même niveau, sans autre exception. Qui cède ?|You fly north. An ordinary powered aeroplane converges from the east at the same level, with no other exception. Who gives way?|Vous, car il est à votre droite~L’autre, car vous êtes à sa gauche~Celui dont le cap est le plus petit~Celui qui vole vers l’ouest|You, because it is on your right~The other, because you are on its left~The aircraft with the smaller heading~The aircraft flying west|Identifier droite et gauche depuis le cockpit : le trafic venant de l’est est à droite du pilote orienté au nord.|Identify sides from the cockpit: traffic from the east is on the right of a northbound pilot.
1|Vous êtes prioritaire mais la collision devient imminente. Que faire ?|You have right of way but collision becomes imminent. What should you do?|Agir pour éviter la collision~Maintenir la trajectoire quoi qu’il arrive~Attendre obligatoirement une clairance~Fermer la radio pour se concentrer|Act to avoid collision~Maintain the flight path regardless~Always wait for a clearance~Switch off the radio to concentrate|SERA.3201 maintient la responsabilité d’éviter une collision même lorsqu’on est prioritaire.|SERA.3201 retains collision avoidance responsibility even with right of way.
1|En convergence, vous devez céder. Passer juste devant l’autre avion est-il approprié ?|You must give way in a converging encounter. Is passing just ahead appropriate?|Non, il faut rester largement à l’écart~Oui, si votre avion est prioritaire au roulage~Oui, si vous annoncez votre intention~Oui, si vos vitesses sont égales|No, remain well clear~Yes, if your aircraft has taxi priority~Yes, if you announce your intention~Yes, if speeds are equal|Céder exige un écart suffisant, en tenant compte du sillage ; une annonce ne remplace pas cette obligation.|Giving way requires sufficient clearance, accounting for wake; an announcement does not replace this duty.
2|Votre avion motorisé converge avec un planeur au même niveau. Le planeur est à gauche. Qui cède ?|Your powered aeroplane converges with a sailplane at the same level. The sailplane is on the left. Who gives way?|Votre avion~Le planeur, toujours~Celui qui descend uniquement~Celui dont la radio est éteinte|Your aeroplane~The sailplane, always~Only the descending aircraft~The aircraft with its radio off|L’exception en faveur du planeur prime sur la règle générale de convergence.|The sailplane exception takes precedence over the general convergence rule.
2|Vous voyez un avion remorquer un planeur sur une trajectoire convergente. Quelle règle appliquer ?|You see an aircraft towing a sailplane on a converging track. Which rule applies?|Votre avion motorisé lui cède~Le remorqueur cède toujours~Le plus lent cède~La priorité dépend du nombre de passagers|Your powered aeroplane gives way~The tug always gives way~The slower aircraft gives way~Priority depends on passenger count|SERA.3210 prévoit la priorité de l’aéronef vu en remorquage sur l’aéronef motorisé concerné.|SERA.3210 requires the powered aircraft to give way to an aircraft seen towing.
2|Votre avion rattrape un autre avion par l’arrière. De quel côté le dépasser ?|Your aeroplane overtakes another from behind. On which side should you pass?|À droite en restant à l’écart~À gauche obligatoirement~Du côté de votre choix sans restriction~Juste au-dessus|On the right while keeping clear~Always on the left~Either side without restriction~Just above|Pour un avion, le dépassement s’effectue par modification de cap à droite.|An overtaking aeroplane alters heading to the right.
2|Pendant votre dépassement, l’avion rattrapé change légèrement de direction. Quand votre obligation de rester à l’écart prend-elle fin ?|During overtaking, the overtaken aircraft changes direction slightly. When does your duty to keep clear end?|Une fois entièrement passé et dégagé~Dès que vous êtes à sa droite~Dès qu’il change de cap~Dès que vous le voyez sous l’aile|When entirely past and clear~As soon as you are on its right~As soon as it changes heading~As soon as you see it below the wing|L’évolution des positions relatives ne supprime pas l’obligation du pilote qui dépasse.|Changing relative positions does not remove the overtaking pilot’s obligation.
3|Un avion roule et un autre est en finale pour atterrir. Lequel a priorité ?|One aircraft is taxiing and another is on final to land. Which has priority?|Celui en finale~Celui au sol~Celui dont la masse est supérieure~Celui qui appelle en premier|The aircraft on final~The aircraft on the ground~The heavier aircraft~The first to call|La priorité à l’atterrissage concerne aussi les aéronefs au sol.|Landing priority also applies to aircraft on the surface.
3|Vous êtes plus bas qu’un avion déjà établi en finale. Pouvez-vous couper devant lui pour atterrir ?|You are lower than an aircraft already on final. May you cut ahead to land?|Non~Oui, la hauteur donne une priorité absolue~Oui, si vous êtes plus lent~Oui, si vous réduisez la radio|No~Yes, height gives absolute priority~Yes, if you are slower~Yes, if you reduce radio use|La règle du plus bas n’autorise ni à couper devant un aéronef en finale ni à le dépasser.|The lower-aircraft rule does not permit cutting ahead of or overtaking an aircraft on final.
3|Vous savez qu’un aéronef doit effectuer un atterrissage forcé. Quelle conduite adopter ?|You know an aircraft must make a forced landing. What should you do?|Lui céder le passage~Exiger qu’il attende votre atterrissage~Appliquer uniquement la priorité à droite~Lui demander de monter avant de décider|Give way to it~Require it to wait for your landing~Apply only the right-hand rule~Ask it to climb before deciding|La situation d’atterrissage forcé impose de lui céder.|Give way to an aircraft known to be making a forced landing.
4|Au roulage, votre trajectoire croise celle d’un avion sur le point de décoller. Qui cède ?|While taxiing, your path conflicts with an aircraft about to take off. Who gives way?|Vous~L’avion au départ~Celui à gauche, sans autre règle~Celui qui a le moins de carburant|You~The departing aircraft~The aircraft on the left, with no other rule~The aircraft with less fuel|Un aéronef au roulage cède à celui qui décolle ou va décoller.|A taxiing aircraft gives way to one taking off or about to take off.
4|Sur un aérodrome contrôlé, vous atteignez un point d’attente sans clairance d’entrée ni de traversée. Que faire ?|At a controlled aerodrome, you reach a runway holding position without entry or crossing clearance. What should you do?|Vous arrêter avant le point d’attente~Traverser si la piste paraît vide~Suivre l’avion précédent sans autre échange~Traverser après une annonce unilatérale|Stop before the holding position~Cross if the runway looks empty~Follow the preceding aircraft without further exchange~Cross after a one-way announcement|Une clairance explicite est nécessaire ; voir une piste libre ne suffit pas.|Explicit clearance is required; seeing an empty runway is insufficient.
4|Vous recevez une clairance de traversée mais la barre d’arrêt reste rouge. Quelle action ?|You receive crossing clearance but the stop bar remains red. What should you do?|Rester arrêté et demander clarification~Traverser grâce à la clairance seule~Traverser si personne ne vient~Éteindre vos feux et avancer|Remain stopped and request clarification~Cross on the clearance alone~Cross if no one is approaching~Switch off your lights and proceed|La clairance ne permet pas à elle seule de franchir une barre d’arrêt allumée.|Clearance alone does not permit crossing a lighted stop bar.
4|La barre d’arrêt s’éteint mais vous n’avez pas reçu la clairance requise de traversée. Pouvez-vous traverser ?|The stop bar goes out but you have not received the required crossing clearance. May you cross?|Non, obtenir aussi la clairance~Oui, l’extinction suffit toujours~Oui, après dix secondes~Oui, avec le transpondeur en marche|No, obtain clearance as well~Yes, extinction is always sufficient~Yes, after ten seconds~Yes, with the transponder on|Extinction et clairance requise sont deux conditions distinctes.|An extinguished bar and the required clearance are separate conditions.''', [
        ('Face à face', 'Head-on', 'Risque de collision : chacun vire à sa droite.', 'Collision risk: both turn to their own right.'),
        ('Convergence', 'Converging', 'Même niveau : céder au trafic à droite, sauf exceptions.', 'Same level: give way to traffic on the right, subject to exceptions.'),
        ('Barre rouge', 'Red stop bar', 'Arrêt. Extinction ET clairance requise avant de passer.', 'Stop. Extinguished bar AND required clearance before crossing.')])

    lesson('PPL_AIRLAW_013', 'air_law', 'Classes d’espace et services ATS', 'Airspace classes and ATS services', SERA, [
        ('Identifier le volume et les conditions', 'Identify the volume and conditions',
         'Objectif : séparer trois décisions : accès autorisé, équipement exigé et service effectivement fourni. Vérifier sur les publications à jour les limites latérales et verticales, les horaires, les zones et NOTAM. Une classe n’est pas une autorisation de pénétration. La classe A admet seulement les vols IFR. Les classes B à G admettent IFR et VFR, sous les conditions applicables. La classe B sépare tous les vols entre eux. Toutes les classes ne sont pas nécessairement utilisées dans chaque pays. Les minima VMC, les restrictions locales et la clairance éventuelle se vérifient séparément. Les unités d’affichage et la langue ne changent pas le cadre européen de ce cours.',
         'Objective: separate three decisions: permission to enter, required equipment and service actually provided. Check current publications for lateral and vertical limits, operating hours, zones and NOTAMs. A class designation is not an entry authorisation. Class A admits IFR only. Classes B through G admit IFR and VFR subject to applicable conditions. Class B separates all flights from each other. Not every class is necessarily used in every country. Check VMC minima, local restrictions and any clearance requirement separately. Display units and language do not change this course’s European regulatory framework.'),
        ('Comparer C et D en VFR', 'Compare C and D for VFR',
         'En C et D, les vols VFR nécessitent clairance ATC et communications radio bilatérales continues. En C, l’ATC sépare les IFR des IFR et des VFR : un VFR reçoit donc une séparation vis-à-vis des IFR, mais seulement des informations de trafic sur les autres VFR, avec conseil d’évitement sur demande. En D, les IFR sont séparés des autres IFR ; le VFR reçoit des informations de trafic sur les autres vols et des conseils d’évitement sur demande, sans séparation ATC systématique en VFR normal. Exemple : deux VFR en C ne doivent pas déduire de leur clairance qu’ils sont séparés entre eux. La surveillance extérieure reste nécessaire dans les deux classes.',
         'In C and D, VFR flights require ATC clearance and continuous two-way radio communication. In C, ATC separates IFR from IFR and VFR: a VFR flight therefore receives separation from IFR, but traffic information about other VFR flights, with avoidance advice on request. In D, IFR flights are separated from other IFR flights; a VFR flight receives information about other traffic and avoidance advice on request, without systematic ATC separation for normal VFR. Example: two VFR flights in C must not infer from their clearances that they are separated from each other. Outside lookout remains necessary in both classes.'),
        ('Comprendre E, F et G', 'Understand E, F and G',
         'En E, les IFR sont contrôlés et séparés des autres IFR. Le VFR normal ne requiert pas de clairance du seul fait de la classe E ; l’information de trafic est fournie dans la mesure du possible. Des exigences supplémentaires, notamment une RMZ, peuvent imposer la radio. La classe E ne sert pas à une zone de contrôle CTR. En F, les IFR participants reçoivent un service consultatif ; cette classification est temporaire. En F et G, un service d’information de vol est disponible sur demande et la classe seule n’impose pas de clairance ATC. Un contact avec un service d’information de vol ne signifie pas séparation assurée. En VFR, la limite générale est 250 kt IAS sous 10 000 ft AMSL en C à G, sous réserve des exceptions autorisées.',
         'In E, IFR flights are controlled and separated from other IFR flights. Normal VFR does not require clearance solely because the airspace is E; traffic information is provided as far as practicable. Additional requirements, such as an RMZ, may require radio. E is not used for a control zone (CTR). In F, participating IFR flights receive an advisory service; this classification is temporary. In F and G, flight information service is available on request and the class alone does not require ATC clearance. Contact with a flight information service does not mean separation is provided. For VFR, the general speed limit is 250 kt IAS below 10,000 ft AMSL in C through G, subject to authorised exceptions.'),
        ('RMZ et TMZ', 'RMZ and TMZ',
         'Une RMZ est une zone à utilisation obligatoire de radio. Pour le VFR en E, F ou G désigné RMZ, maintenir l’écoute et établir les communications bilatérales nécessaires, sauf dispositions alternatives publiées par le prestataire. Avant l’entrée, l’appel initial comporte la station appelée, l’indicatif, le type d’aéronef, la position, le niveau et les intentions, ainsi que les autres éléments prescrits. Une TMZ impose un transpondeur SSR fonctionnel en modes A et C, ou S, sauf dispositions alternatives prescrites ; le mode A seul ne suffit pas. RMZ et TMZ sont publiées dans l’AIP et peuvent se superposer. Ce sont des exigences distinctes, pas de nouvelles classes. Vérifier les procédures locales avant le vol.',
         'An RMZ is a radio mandatory zone. For VFR in E, F or G designated as an RMZ, maintain a listening watch and establish the necessary two-way communication unless the provider publishes alternative provisions. Before entry, the initial call includes the called station, callsign, aircraft type, position, level and intentions, plus other prescribed information. A TMZ requires an operating SSR transponder in modes A and C, or S, unless prescribed alternatives apply; mode A alone is insufficient. RMZs and TMZs are published in the AIP and can overlap. They are separate requirements, not new classes. Check local procedures before flight.')],
        '''1|Vous prévoyez un transit VFR dans une classe A. Que conclure de la classification standard ?|You plan a VFR transit through class A. What follows from the standard classification?|Seuls les vols IFR y sont admis~Un contact radio autorise le VFR~Le VFR est admis sans clairance~Le VFR est admis seulement avec transpondeur|Only IFR flights are admitted~Radio contact authorises VFR~VFR is admitted without clearance~VFR is admitted only with a transponder|SERA.6001 réserve la classe A aux vols IFR.|SERA.6001 reserves class A for IFR flights.
1|Une carte montre un espace sur votre route. Quelle vérification permet de savoir si votre trajectoire le traverse réellement ?|A chart shows airspace along your route. What determines whether your flight path actually enters it?|Limites latérales et verticales, activité et informations à jour~La couleur seule, sans légende~Le nom de l’aéroport voisin uniquement~La langue choisie dans l’application|Lateral and vertical limits, activity and current information~Colour alone, without a legend~Only the nearby airport’s name~The language selected in the application|L’espace est un volume dont les conditions publiées et l’activité doivent être vérifiées.|Airspace is a volume whose published conditions and activity must be checked.
1|Quelle classe fournit une séparation ATC entre tous les vols IFR et VFR ?|Which class provides ATC separation between all IFR and VFR flights?|B~D~E~G|B~D~E~G|En classe B, tous les vols sont séparés entre eux.|In B, all flights are separated from each other.
2|Vous êtes VFR en classe C. De quel trafic recevez-vous une séparation ATC ?|You are VFR in class C. From which traffic do you receive ATC separation?|Des IFR~De tous les VFR seulement~De tous les vols sans distinction~D’aucun trafic|IFR flights~Only all VFR flights~All flights without distinction~No traffic|En C, la séparation IFR/VFR est assurée ; les autres VFR font l’objet d’informations de trafic.|In C, IFR/VFR separation is provided; other VFR flights are subject to traffic information.
2|Deux VFR disposent chacun d’une clairance en classe C. Leur séparation mutuelle est-elle systématiquement assurée par l’ATC ?|Two VFR flights each have clearance in class C. Does ATC systematically separate them from each other?|Non, ils reçoivent des informations de trafic~Oui, comme en classe B~Oui, uniquement sous 10 000 ft~Oui, s’ils parlent anglais|No, they receive traffic information~Yes, as in class B~Yes, only below 10,000 ft~Yes, if they speak English|Ne pas confondre séparation et information de trafic.|Do not confuse separation with traffic information.
2|En VFR normal en classe D, quel service attendre vis-à-vis d’un IFR ?|In normal VFR in class D, what service should you expect concerning an IFR flight?|Information de trafic et conseil d’évitement sur demande~Séparation ATC systématique IFR/VFR~Aucun renseignement de trafic possible~Une priorité absolue sur l’IFR|Traffic information and avoidance advice on request~Systematic ATC IFR/VFR separation~No traffic information can be provided~Absolute priority over IFR|La séparation IFR/VFR de la classe C ne doit pas être transférée à la classe D.|Class C IFR/VFR separation must not be assumed in D.
2|La station vous répond avec votre indicatif mais ne vous autorise pas à entrer en classe D. Pouvez-vous pénétrer ?|The station replies with your callsign but does not clear entry into class D. May you enter?|Non, obtenir la clairance requise~Oui, l’accusé de réception suffit~Oui, en respectant seulement les minima VMC~Oui, après avoir affiché un code transpondeur|No, obtain the required clearance~Yes, acknowledgement is sufficient~Yes, by meeting VMC minima alone~Yes, after setting a transponder code|Un contact radio n’est pas une clairance ATC.|Radio contact is not an ATC clearance.
3|En VFR normal en classe E, sans zone ni restriction supplémentaire, la classe seule impose-t-elle une clairance ?|In normal VFR in class E, with no additional zone or restriction, does the class alone require clearance?|Non~Oui, pour tous les VFR~Oui, seulement si le ciel est dégagé~Oui, seulement avec un moteur à pistons|No~Yes, for every VFR flight~Yes, only in clear skies~Yes, only with a piston engine|En E, le contrôle et la clairance concernent les IFR ; vérifier les exigences supplémentaires applicables au VFR.|In E, control and clearance apply to IFR; check additional requirements applicable to VFR.
3|En classe G, vous contactez un service d’information de vol. Cela garantit-il votre séparation des autres aéronefs ?|In class G, you contact a flight information service. Does this guarantee separation from other aircraft?|Non~Oui, dès le premier appel~Oui, avec un code transpondeur attribué~Oui, si vous transmettez votre altitude|No~Yes, from the first call~Yes, with an assigned transponder code~Yes, if you report altitude|Le service d’information de vol ne fournit pas une séparation ATC.|Flight information service does not provide ATC separation.
3|En VFR à 5 000 ft AMSL en classe D, sans exception autorisée, quelle limite générale IAS s’applique ?|VFR at 5,000 ft AMSL in class D, with no authorised exception: which general IAS limit applies?|250 kt~200 kt~300 kt~Aucune limite liée à la classe|250 kt~200 kt~300 kt~No class-related limit|La limite générale de 250 kt IAS s’applique au VFR sous 10 000 ft AMSL en C à G.|The general 250 kt IAS limit applies to VFR below 10,000 ft AMSL in C through G.
3|Quel service caractérise les IFR participants en classe F ?|Which service characterises participating IFR flights in class F?|Service consultatif de la circulation aérienne~Séparation de tous les vols comme en B~Clairance VFR obligatoire comme en D~Absence de tout service possible|Air traffic advisory service~Separation of all flights as in B~Mandatory VFR clearance as in D~No service can be available|La classe F prévoit un service consultatif pour les IFR participants et une information de vol sur demande.|F provides advisory service for participating IFR and flight information on request.
4|Votre route VFR traverse une RMZ en classe G. Sans disposition alternative, quelle préparation est nécessaire ?|Your VFR route crosses an RMZ in class G. Without alternative provisions, what is required?|Appel initial avant l’entrée, écoute et communications requises~Aucune radio puisque la classe est G~Un transpondeur seul remplace la radio~Un appel seulement après la sortie|Initial call before entry, listening watch and required communication~No radio because the class is G~A transponder alone replaces radio~A call only after exit|La RMZ ajoute une exigence radio à la classe de base.|An RMZ adds a radio requirement to the underlying class.
4|Quel message initial convient avant une entrée en RMZ ?|Which initial call is appropriate before RMZ entry?|Station, indicatif, type, position, niveau et intentions~Indicatif seul sans position~Nombre de passagers uniquement~Message après l’entrée sans niveau|Station, callsign, type, position, level and intentions~Callsign alone without position~Passenger count only~Message after entry without level|SERA.6005 énumère ces éléments, complétés par les informations prescrites localement.|SERA.6005 lists these elements, supplemented by locally prescribed information.
4|Une TMZ est publiée sans disposition alternative. Un transpondeur fonctionnant uniquement en mode A suffit-il ?|A TMZ is published without alternative provisions. Is a transponder operating only in mode A sufficient?|Non, modes A et C ou S requis~Oui, tout code suffit~Oui, avec une radio portative~Oui, uniquement en VFR|No, modes A and C or S are required~Yes, any code is sufficient~Yes, with a handheld radio~Yes, in VFR only|Le mode A seul ne répond pas à l’exigence de SERA.6005 pour une TMZ.|Mode A alone does not meet the SERA.6005 TMZ requirement.
4|Une zone est à la fois RMZ et TMZ. Que faut-il examiner ?|A zone is both an RMZ and a TMZ. What must be checked?|Les exigences radio et transpondeur, ainsi que les règles de la classe~La radio seulement~Le transpondeur seulement~Une nouvelle classe appelée RMZ-TMZ|Radio and transponder requirements, plus the class rules~Radio only~Transponder only~A new class called RMZ-TMZ|Les deux exigences se cumulent ; elles ne remplacent pas la classification de l’espace.|Both requirements apply; they do not replace the airspace classification.''', [
        ('VFR en C', 'VFR in C', 'Clairance + radio. Séparation des IFR ; information sur les VFR.', 'Clearance + radio. Separation from IFR; information about VFR.'),
        ('VFR en D', 'VFR in D', 'Clairance + radio. Information de trafic ; pas de séparation systématique.', 'Clearance + radio. Traffic information; no systematic separation.'),
        ('RMZ / TMZ', 'RMZ / TMZ', 'RMZ : radio. TMZ : transpondeur. Vérifier les deux exigences.', 'RMZ: radio. TMZ: transponder. Check both requirements.')])

    references = {'PPL_AIRLAW_012': ['SERA.3201; SERA.3210(c)(1)-(2)', 'SERA.3210(b); (c)(2)-(3)', 'SERA.3210(c)(4)', 'SERA.3210(c)(5); (d)'], 'PPL_AIRLAW_013': ['SERA.6001', 'SERA.6001(c)-(d)', 'SERA.6001(e)-(g)', 'SERA.6005']}
    for module, refs in references.items():
        path = ROOT / 'content/fr/ppl/air_law' / (module + '_application.json')
        data = json.loads(path.read_text(encoding='utf-8'))
        data['metadata']['reference_checked_on'] = '2026-09-22'
        data['metadata']['prerequisites'] = ['PPL_AIRLAW_011']
        for concept, ref in zip(data['concepts'], refs):
            concept['regulatory_reference'] = ref
        for question in data['questions']:
            question['regulatory_reference'] = next(c['regulatory_reference'] for c in data['concepts'] if c['concept_id'] == question['concept_id'])
        path.write_text(json.dumps(data, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    main()
